const today = new Date();
const results = [];

// STEP 1: Remove duplicate emails - keep only the first occurrence of each email
// (in case same lead got added twice in the sheet by mistake)
const seenEmails = new Set();
const uniqueRows = [];

for (const item of $input.all()) {
  const email = (item.json.Email || '').toLowerCase().trim();
  if (!email) continue; // skip rows with no email at all
  if (seenEmails.has(email)) {
    continue; // skip duplicate, already processed this email once
  }
  seenEmails.add(email);
  uniqueRows.push(item);
}

// STEP 2: existing logic runs only on the de-duplicated list
for (const item of uniqueRows) {
  const row = item.json;
  const status = (row.Status || 'New').trim();
  const lastContact = row.LastContactDate ? new Date(row.LastContactDate) : null;
  const daysSince = lastContact ? Math.floor((today - lastContact) / (1000 * 60 * 60 * 24)) : null;

  let action = null;

  if (status === 'New' || status === '') {
    action = 'send_email_1';
  } else if (status === 'Email1Sent' && daysSince !== null && daysSince >= 4) {
    action = 'send_followup_1';
  } else if (status === 'Followup1Sent' && daysSince !== null && daysSince >= 5) {
    action = 'send_followup_2';
  } else if (status === 'Followup2Sent' && daysSince !== null && daysSince >= 7) {
    action = 'send_followup_3_breakup';
  }

  if (action) {
    results.push({
      json: {
        ...row,
        action
      }
    });
  }
}

return results;

// Strip HTML tags down to plain text and truncate so we don't blow up the AI prompt.
// If the website fetch failed, fall back to just Company + Industry for the AI to work with.
const leadRow = $('Route By Stage').item.json;
let rawHtml = '';
try {
  rawHtml = $input.first().json.data || $input.first().json.body || '';
  if (typeof rawHtml !== 'string') rawHtml = JSON.stringify(rawHtml);
} catch (e) {
  rawHtml = '';
}
let text = rawHtml
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();
// Keep prompt small and cheap
text = text.slice(0, 3000);

// --- Booking slot logic: compute suggested days + a random EST time (9am-3pm) based on NY send day ---
const nyNow = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/New_York' }));
const dayIndex = nyNow.getDay(); // 0=Sun...6=Sat

const dayNames = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const suggestionMap = {
  0: ['Monday', 'Tuesday'],    // Sunday send -> fallback
  1: ['Tuesday', 'Wednesday'], // Monday send
  2: ['Wednesday', 'Thursday'],// Tuesday send
  3: ['Thursday', 'Friday'],   // Wednesday send
  4: ['Friday', 'Monday'],     // Thursday send
  5: ['Monday', 'Tuesday'],    // Friday send
  6: ['Monday', 'Tuesday']     // Saturday send -> fallback
};
const suggestedDays = suggestionMap[dayIndex];

// Random time between 9:00am and 3:00pm EST, in 30-min increments
const slots = [];
for (let h = 9; h <= 14; h++) {
  slots.push({ h, m: 0 });
  if (h !== 14) slots.push({ h, m: 30 }); // stop adding past 3:00pm
}
const pick = slots[Math.floor(Math.random() * slots.length)];
const hour12 = pick.h > 12 ? pick.h - 12 : pick.h;
const ampm = pick.h >= 12 ? 'pm' : 'am';
const minuteStr = pick.m === 0 ? '00' : String(pick.m);
const suggestedTime = `${hour12}:${minuteStr}${ampm} EST`;

const bookingSuggestion = `${suggestedDays[0]} or ${suggestedDays[1]} around ${suggestedTime}`;

const requestBodyObj = {
  model: 'gpt-4o-mini',
  response_format: { type: 'json_object' },
  temperature: 0.7,
  max_tokens: 450,
  messages: [
    {
      role: 'system',
      content: "You are one of the world's top B2B cold email copywriters â the kind agencies hire specifically because your emails get replies, never sound templated, and never come across as pushy or amateur. You are writing on behalf of The Deft Crew, a growth-focused, full-service marketing agency that also builds mobile/web apps and automation (n8n) solutions.\n\nYour job has two parts:\n\nPART 1 - DIAGNOSE THE REAL PROBLEM (not a generic one):\nGiven the lead's company, industry, and website text, identify ONE realistic, SPECIFIC operational pain point this type of business actually deals with day-to-day â something they'd read and think 'yes, that's exactly our problem,' not a vague line like 'reaching your audience.' Think in terms of repetitive, resource-draining operational work specific to their industry â examples of the KIND of specificity to aim for (do not reuse these verbatim, adapt to the lead's real industry): a marketing agency drowning in monthly content calendars, caption writing, strategy research, resource planning, client coordination, lead follow-up, onboarding, and feedback loops; a clinic buried in appointment reminders and no-show follow-ups; an e-commerce store manually reconciling inventory across channels and answering the same 10 customer questions all day; a real estate team re-entering the same lead data across 4 tools and forgetting to follow up. Translate this thinking to whatever industry the lead is actually in, based on their website content.\n\nPART 2 - WRITE THE EMAIL BODY (no greeting, that's added separately):\nWrite a cold email body, 70-110 words, in 2-4 short paragraphs separated by \\n\\n, that:\n1. Opens by naming the SPECIFIC pain point above in a way that shows you understand their business (reference something real from their website if possible)\n2. Makes a 'door-opener' offer that removes all risk: we will build a working solution/tool for this specific problem in 7 days, they can try it free for 7 days, and only if it's genuinely valuable do they hire us for the full project or a retainer â otherwise it costs them nothing\n3. Ends with a single low-pressure question offering a call, using the exact suggested days and time provided in the user message (formatted like: 'Suggested availability: <days> around <time>'). Do not say '15-minute call' or mention any time range â just naturally weave in the specific day(s) and time given, phrased as a casual question (e.g., 'Are you free Tuesday or Wednesday around 11:00am EST? Our director has that slot open for a quick call.')\nTone: confident, direct, human â no exclamation marks, no hype words ('amplify', 'unlock', 'revolutionize', 'game-changer'), no corporate filler.\n\nRespond ONLY as JSON: {\"service\": \"marketing|app_dev|automation\", \"pain_point\": \"...\", \"subject\": \"...\", \"email_body\": \"...\"}. Keep pain_point to 4-8 words, specific and concrete (e.g. 'manual lead follow-up and onboarding', 'juggling content calendars across clients'), not generic."
    },
    {
      role: 'user',
      content: `Company: ${leadRow.Company}\nIndustry: ${leadRow.Industry}\nWebsite text: ${text}\nSuggested availability: ${bookingSuggestion}`
    }
  ]
};
return [{
  json: {
    ...leadRow,
    requestBody: JSON.stringify(requestBodyObj)
  }
}];

const leadRow = $('Extract Website Text').item.json;

let parsed = { service: '', pain_point: '', subject: '', email_body: '' };
try {
  const content = $input.first().json.choices[0].message.content;
  parsed = JSON.parse(content);
} catch (e) {
  parsed = {
    service: 'automation',
    pain_point: 'manual, repetitive workflows',
    subject: `quick question about ${leadRow.Company}`,
    email_body: `Noticed ${leadRow.Company} is active in the ${leadRow.Industry} space. We recently helped a similar company automate manual workflows and save significant time.\n\nWorth a quick chat to see if something similar could help?`
  };
}

// Convert AI's \n\n paragraph breaks into HTML <br><br> so they render correctly
// when the email is sent in HTML format instead of plain text.
const emailBodyHtml = (parsed.email_body || '')
  .split('\n\n')
  .map(paragraph => paragraph.trim())
  .filter(paragraph => paragraph.length > 0)
  .join('<br><br>');

const { websiteText, requestBody, ...cleanRow } = leadRow;

return [{
  json: {
    ...cleanRow,
    Service: parsed.service,
    PainPoint: parsed.pain_point,
    EmailSubject: parsed.subject,
    EmailBody: emailBodyHtml
  }
}];

const routeData = $('Route By Stage').item.json;

const statusMap = {
  'send_email_1': 'Email1Sent',
  'send_followup_1': 'Followup1Sent',
  'send_followup_2': 'Followup2Sent',
  'send_followup_3_breakup': 'Followup3Sent'
};

let painPoint = routeData.PainPoint;
let service = routeData.Service;

if (routeData.action === 'send_email_1') {
  const aiData = $('Parse AI Response').item.json;
  painPoint = aiData.PainPoint;
  service = aiData.Service;
}

return [{
  json: {
    Email: routeData.Email,
    Status: statusMap[routeData.action] || routeData.action,
    LastContactDate: new Date().toISOString().split('T')[0],
    PainPoint: painPoint,
    Service: service
  }
}];
